namespace FairShare.Application.DTOs.Payments;

public class PayWithCardRequest
{
    public Guid PaymentCardId { get; set; }

    /// <summary>
    /// Generated by the frontend once per payment attempt (e.g. a GUID) and sent again if the
    /// request is repeated. The same key never charges twice - the first result is returned.
    /// </summary>
    public string IdempotencyKey { get; set; } = string.Empty;
}
